insert into public.activities (id,name,description,category,sort_order) values
('mesa-redonda', 'Mesa-redonda', 'Três ex-alunos e um professor da casa debatem suas jornadas reais, desde a sala de aula até os desafios da área tech. A conversa aborda como o curso moldou suas visões, a transição para o mercado de trabalho e os principais aprendizados profissionais colhidos na área.', 'Carreira e experiências', 1),
('trabalhando-com-dados', 'Trabalhando com Dados nos dias atuais', 'A apresentação aborda as principais funções, ferramentas e a rotina da área de dados, demonstrando como ferramentas de integração, data lake e data viz se conectam no dia a dia.', 'Dados', 2),
('tecnologia-ia-oportunidades', 'Tecnologia, Inteligência Artificial e Oportunidades para o Futuro', 'Conduzido pelo instrutor Vitor Mello junto a alunos de destaque, o encontro aborda a formação tecnológica, o uso de Inteligência Artificial na transformação social e cases de sucesso no desenvolvimento de projetos reais.', 'Inteligência Artificial', 3),
('iniciacao-cientifica', 'Apresentações de Iniciação Científica', 'Confira a integração entre tecnologia, direito e sociedade na UFRRJ: pesquisas sobre o mapeamento de conexões interdisciplinares com Redes Complexas (UniHub), a aplicação de LLMs no Direito Digital para classificação de condutas e o uso de RAG em redes federadas para facilitar o acesso à informação acadêmica.', 'Pesquisa', 4),
('linkedin-curriculo-entrevista', 'LinkedIn, currículo e entrevista: construindo sua jornada profissional', 'O bate-papo explora como valorizar competências, conquistar oportunidades e utilizar a Inteligência Artificial de forma estratégica.', 'Carreira e experiências', 5),
('da-rural-ao-canada', 'Da Rural ao Canadá', 'O encontro aborda desafios, conquistas, experiências de empreendedorismo (incluindo o fracasso de uma startup), o trabalho em empresas internacionais e os caminhos para construir carreira fora do país.', 'Carreira e experiências', 6),
('e-se-a-aws-fosse-um-jogo', 'E se a AWS fosse um jogo?', 'Uma abordagem lúdica e acessível da Amazon Web Services, utilizando analogias com o universo dos games para explorar ferramentas, caminhos e os principais serviços da plataforma.', 'Computação em nuvem', 7),
('meninas-na-robotica', 'Meninas na Robótica', 'Apresentação de projetos desenvolvidos pelo grupo, demonstrando o trabalho realizado na união entre criatividade, experimentação e tecnologia. A atividade busca incentivar o interesse pela robótica e evidenciar a inclusão de meninas na área.', 'Robótica', 8),
('equipe-robotica-shield-nig', 'Equipe de Robótica SHIELD NIG', 'Descubra como a SHIELD NIG transforma ideias em robôs de alta performance em um bate-papo com Gabriel e a equipe premiada no Torneio Brasil de Robótica.', 'Robótica', 9),
('sua-ideia-vale-uma-startup', 'Sua ideia vale uma startup?', 'A palestra apresenta um caminho estratégico para transformar ideias, TCCs e pesquisas acadêmicas em startups viáveis na região, mostrando o cenário atual de apoio legal e financeiro, como o Marco Legal das Startups e editais de fomento.', 'Empreendedorismo', 10),
('visao-sobre-ai-gateway', 'Uma visão sobre AI Gateway', 'Abordagem sobre o erro comum de chamar modelos de IA de forma direta, apresentando padrões de projeto alternativos e explicando como os AI Gateways solucionam esse problema na arquitetura de sistemas.', 'Inteligência Artificial', 11),
('ciencia-computacao-alem-software', 'Ciência da Computação além das empresas de software', 'O encontro aborda a entrada no mercado de trabalho, o valor das oportunidades acadêmicas e os desafios de atuar como desenvolvedor em um ambiente multidisciplinar, mostrando como aplicar conhecimentos da graduação em automação, inovação e resolução de problemas reais.', 'Carreira e experiências', 12),
('kafka-alem-das-filas', 'Kafka além das filas', 'Entenda como o Apache Kafka funciona por dentro e quais padrões tornam sistemas orientados a eventos confiáveis.', 'Engenharia de software', 13),
('como-iniciar-em-ia-security', 'Como iniciar em IA Security', 'A apresentação explora as mudanças na superfície de ataque, as principais ameaças voltadas a aplicações e agentes com inteligência artificial, além de estratégias de defesa.', 'Segurança', 14),
('como-e-desenvolver-um-jogo', 'Como é desenvolver um jogo?', 'A palestra aborda o desenvolvimento do Desafiaula, um jogo multiplayer que transforma disciplinas escolares em minigames interativos em Unity.', 'Desenvolvimento de jogos', 15)
